/**
 * How Three divided floral crosses (`mitsuwari-kurusu`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/mitsuwari-kurusu";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Strike the round field and draw three pairs of arcs about centres on its rim. Leave the petal seams, the three central darts and the three small rim darts white.","ja":"丸い地を打ち、その縁に置いた三つの中心からそれぞれ二本の弧を引きます。花びらの境、中央の三つのとがり、縁の三つの小さなとがりを白く残します。"};

export default construction;
export { construction, description };
